// Never throws unhandled -- same generic-contract convention as LLM
// Gateway's 'Parse Gemini response': always { success, ... }, never a raw
// throw a calling workflow would have to catch.
try {
  const response = $json || {};

  if (response.error) {
    const message =
      (typeof response.error === 'string' && response.error) ||
      (response.error && response.error.message) ||
      'Request to Telegram sendMessage failed';
    return { json: { success: false, error: String(message) } };
  }

  const statusCode = response.statusCode;
  const body = response.body || {};

  if (!statusCode || statusCode < 200 || statusCode >= 300) {
    const apiMessage = body.description || `Telegram sendMessage returned HTTP ${statusCode}`;
    return { json: { success: false, error: String(apiMessage) } };
  }

  return { json: { success: true, message_id: body.result && body.result.message_id } };
} catch (err) {
  return { json: { success: false, error: (err && err.message) || 'Unknown Telegram Send error' } };
}
